  <script type="module">
    function createLeaves() {
      const container = $('.leaf-container');
      if (container.children().length > 0) return;
      for (let i = 0; i < 15; i++) {
        const leaf = $('<div>').addClass('leaf');
        leaf.css({
          left: `${Math.random() * 100}vw`,
          animationDuration: `${Math.random() * 10 + 8}s`,
          animationDelay: `${Math.random() * 5}s`,
          transform: `scale(${Math.random() * 0.5 + 0.5})`
        });
        container.append(leaf);
      }
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();
      const statData = _.get(all_variables, 'stat_data', {});

      $('#date-value').text(_.get(statData, '日期', ['N/A'])[0]);
      $('#time-value').text(_.get(statData, '时间', ['N/A'])[0]);
      $('#location-value').text(_.get(statData, 'user.位置', ['未知'])[0]);

      // --- 姜禾数据 ---
      const jiangHeHeartbreak = _.get(statData, '姜禾.变心值', [0])[0];
      $('#jianghe-heartbreak-value').text(`${jiangHeHeartbreak}%`);
      $('#jianghe-progress-bar .progress-hearts').css({
        '-webkit-mask-size': `${jiangHeHeartbreak}% 100%`,
        'mask-size': `${jiangHeHeartbreak}% 100%`
      });

      const jiangHeOutfit = _.get(statData, '姜禾.穿着', {});
      $('#jianghe-outfit-top').text(jiangHeOutfit.上衣?.[0] || 'N/A');
      $('#jianghe-outfit-bottom').text(jiangHeOutfit.下装?.[0] || 'N/A');
      $('#jianghe-outfit-socks').text(jiangHeOutfit.袜子?.[0] || 'N/A');
      $('#jianghe-outfit-shoes').text(jiangHeOutfit.鞋子?.[0] || 'N/A');

      // --- 林晚星数据 ---
      const linWanxingHeartbreak = _.get(statData, '林晚星.变心值', [0])[0];
      $('#linwanxing-heartbreak-value').text(`${linWanxingHeartbreak}%`);
      $('#linwanxing-progress-bar .progress-hearts').css({
          '-webkit-mask-size': `${linWanxingHeartbreak}% 100%`,
          'mask-size': `${linWanxingHeartbreak}% 100%`
      });

      const linWanxingOutfit = _.get(statData, '林晚星.穿着', {});
      $('#linwanxing-outfit-top').text(linWanxingOutfit.上衣?.[0] || 'N/A');
      $('#linwanxing-outfit-bottom').text(linWanxingOutfit.下装?.[0] || 'N/A');
      $('#linwanxing-outfit-socks').text(linWanxingOutfit.袜子?.[0] || 'N/A');
      $('#linwanxing-outfit-shoes').text(linWanxingOutfit.鞋子?.[0] || 'N/A');

      // --- 追求者剧情数据 ---
      const pursuersAllData = _.get(statData, '追求者们', {});
      const pursuersToday = pursuersAllData.今日出场 || {};

      const jhPursuerName = pursuersToday.姜禾场?.[0] || '未知';
      $('#jh-pursuer-name').text(jhPursuerName);
      const jhPursuerData = pursuersAllData[jhPursuerName];
      if(jhPursuerData) {
        $('#jh-pursuer-attitude').text(jhPursuerData.当前心态?.[0] || '未知');
        $('#jh-pursuer-plan').text(jhPursuerData.行动计划?.[0] || '暂无计划');
      } else {
        $('#jh-pursuer-attitude').text('未知');
        $('#jh-pursuer-plan').text('未知');
      }

      const lwxPursuerName = pursuersToday.林晚星场?.[0] || '未知';
      $('#lwx-pursuer-name').text(lwxPursuerName);
      const lwxPursuerData = pursuersAllData[lwxPursuerName];
      if(lwxPursuerData) {
        $('#lwx-pursuer-attitude').text(lwxPursuerData.当前心态?.[0] || '未知');
        $('#lwx-pursuer-plan').text(lwxPursuerData.行动计划?.[0] || '暂无计划');
      } else {
        $('#lwx-pursuer-attitude').text('未知');
        $('#lwx-pursuer-plan').text('未知');
      }
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      createLeaves();
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      // --- [修改后] 新增的点击事件 ---
      $('.plot-summary').on('click', function() {
        $(this).parent('.plot-item').toggleClass('open');
        $(this).siblings('.pursuer-details').slideToggle(300);
      });
    }

    $(errorCatched(init));
  </script>
